CREATE SCHEMA IF NOT EXISTS ap_control;
CREATE TABLE IF NOT EXISTS ap_control.invoices (invoice_id BIGSERIAL PRIMARY KEY, fingerprint TEXT NOT NULL UNIQUE, supplier_id TEXT NOT NULL, invoice_number TEXT NOT NULL, currency CHAR(3) NOT NULL, extracted_fields JSONB NOT NULL, source_hash TEXT NOT NULL, received_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ap_control.match_decisions (decision_id BIGSERIAL PRIMARY KEY, invoice_id BIGINT NOT NULL UNIQUE REFERENCES ap_control.invoices(invoice_id), action TEXT NOT NULL CHECK(action IN ('blocked','exception_review','draft_payable')), reasons JSONB NOT NULL, evidence JSONB NOT NULL, tolerance_version TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ap_control.approvals (approval_id BIGSERIAL PRIMARY KEY, decision_id BIGINT NOT NULL REFERENCES ap_control.match_decisions(decision_id), actor_id TEXT NOT NULL, service_actor BOOLEAN NOT NULL DEFAULT false CHECK(service_actor=false), decision TEXT NOT NULL CHECK(decision IN ('approved','rejected')), decided_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS ap_control.draft_receipts (receipt_id BIGSERIAL PRIMARY KEY, approval_id BIGINT NOT NULL UNIQUE REFERENCES ap_control.approvals(approval_id), erp_draft_id TEXT NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_ap_exception ON ap_control.match_decisions(action,created_at);
